import hashlib
import shutil
import subprocess
from pathlib import Path


def _checksum(path: Path) -> str:
    return hashlib.sha256(path.read_bytes()).hexdigest()


def organise(src: Path, dst: Path) -> None:
    """Copy, verify the postcondition, and only then delete the source."""
    expected_count = len([p for p in src.rglob("*") if p.is_file()])
    result = subprocess.run(["robocopy", str(src), str(dst), "/E"], check=True)
    if result.returncode > 7:
        raise RuntimeError("copy failed; the delete step is ineligible")
    if len([p for p in dst.rglob("*") if p.is_file()]) != expected_count:
        raise RuntimeError("copy incomplete; the delete step is ineligible")
    for original in src.rglob("*"):
        if original.is_file():
            moved = dst / original.relative_to(src)
            if _checksum(original) != _checksum(moved):
                raise RuntimeError("checksum mismatch; delete is ineligible")
    shutil.rmtree(src)
